BEGIN;
DROP POLICY IF EXISTS rls_users_isolation ON public.clinic_users;
CREATE POLICY rls_users_isolation ON public.clinic_users FOR SELECT TO authenticated USING(tenant_id=get_current_tenant_id());
CREATE POLICY ajm1_users_write ON public.clinic_users FOR UPDATE TO authenticated USING(tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'users:update')) WITH CHECK(tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'users:update'));
CREATE POLICY ajm1_users_insert ON public.clinic_users FOR INSERT TO authenticated WITH CHECK(tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'users:create'));
CREATE POLICY ajm1_users_delete ON public.clinic_users FOR DELETE TO authenticated USING(tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'users:delete'));
DROP POLICY IF EXISTS ajm1_cus_write ON public.clinic_user_settings;
CREATE POLICY ajm1_cus_write ON public.clinic_user_settings FOR ALL TO authenticated USING(tenant_id=get_current_tenant_id() AND (user_id=(SELECT id FROM public.clinic_users WHERE auth_user_id=auth.uid() AND tenant_id=get_current_tenant_id()) OR has_tenant_permission(get_current_tenant_id(),'users:update'))) WITH CHECK(tenant_id=get_current_tenant_id() AND (user_id=(SELECT id FROM public.clinic_users WHERE auth_user_id=auth.uid() AND tenant_id=get_current_tenant_id()) OR has_tenant_permission(get_current_tenant_id(),'users:update')));
DROP POLICY IF EXISTS ajm1_uw_write ON public.clinic_user_workspaces;
CREATE POLICY ajm1_uw_write ON public.clinic_user_workspaces FOR ALL TO authenticated USING(tenant_id=get_current_tenant_id() AND (user_id=(SELECT id FROM public.clinic_users WHERE auth_user_id=auth.uid() AND tenant_id=get_current_tenant_id()) OR has_tenant_permission(get_current_tenant_id(),'users:update'))) WITH CHECK(tenant_id=get_current_tenant_id() AND (user_id=(SELECT id FROM public.clinic_users WHERE auth_user_id=auth.uid() AND tenant_id=get_current_tenant_id()) OR has_tenant_permission(get_current_tenant_id(),'users:update')));
DROP POLICY IF EXISTS ajm1_pb_write ON public.permission_bundles;
CREATE POLICY ajm1_pb_write ON public.permission_bundles FOR ALL TO authenticated USING(NOT is_system_bundle AND tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'roles:manage')) WITH CHECK(NOT is_system_bundle AND tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'roles:manage'));
DROP POLICY IF EXISTS ajm1_pbi_write ON public.permission_bundle_items;
CREATE POLICY ajm1_pbi_write ON public.permission_bundle_items FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.permission_bundles b WHERE b.id=bundle_id AND NOT b.is_system_bundle AND b.tenant_id=get_current_tenant_id()) AND has_tenant_permission(get_current_tenant_id(),'roles:manage')) WITH CHECK(EXISTS(SELECT 1 FROM public.permission_bundles b WHERE b.id=bundle_id AND NOT b.is_system_bundle AND b.tenant_id=get_current_tenant_id()) AND has_tenant_permission(get_current_tenant_id(),'roles:manage'));
DROP POLICY IF EXISTS ajm1_rt_write ON public.role_templates;
CREATE POLICY ajm1_rt_write ON public.role_templates FOR ALL TO authenticated USING(NOT is_system_template AND tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'templates:manage')) WITH CHECK(NOT is_system_template AND tenant_id=get_current_tenant_id() AND has_tenant_permission(get_current_tenant_id(),'templates:manage'));
DROP POLICY IF EXISTS ajm1_rtp_write ON public.role_template_permissions;
CREATE POLICY ajm1_rtp_write ON public.role_template_permissions FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.role_templates t WHERE t.id=template_id AND NOT t.is_system_template AND t.tenant_id=get_current_tenant_id()) AND has_tenant_permission(get_current_tenant_id(),'templates:manage')) WITH CHECK(EXISTS(SELECT 1 FROM public.role_templates t WHERE t.id=template_id AND NOT t.is_system_template AND t.tenant_id=get_current_tenant_id()) AND has_tenant_permission(get_current_tenant_id(),'templates:manage'));
COMMIT;
